-- Daily challenges for 2026-10-27: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-27. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('being-present-with-your-kids', 'Being Present with Your Kids', 'For any parent, grandparent or caregiver who wants more unhurried moments with the children in their life, from toddlers to teens. Each day is one small way to put distractions down and simply be with them.', 'Parenting', 365, array['Parenting', 'Family', 'Mindfulness']::text[], 1, '2026-10-27T17:00:00+00:00'::timestamptz),
  ('handling-rejection-gently', 'Handling Rejection Gently', 'For anyone who takes a no hard, whether it comes from a job, a date, a friend or a group. Each day is one small way to steady yourself, keep it in proportion and keep reaching for what matters.', 'Confidence', 365, array['Resilience', 'Self-Esteem', 'Self-Compassion']::text[], 1, '2026-10-27T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('being-present-with-your-kids', 'handling-rejection-gently');

